     "summary": "据“中国光谷”消息，武汉新芯发布“芯光计划”。未来十年，公司将以“光感互联、三维存算”为战略引领，建设具有国际竞争力的特色工艺晶圆制造和三维集成产业平台，打造“3D Link-光电融合-SOI”产业第一极，力争实现产能翻两番，带动超千亿级上下游产业链生态协同发展，引育超1万名半导体高端人才。（文章来源：人民财讯）",
